body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  padding: 2.5rem 1rem 4rem;
  line-height: 1.6;
}

header {
  text-align: center;
  margin-bottom: 2.5rem;
}

header h1 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
}

header p {
  margin-top: .5rem;
  color: var(--color-text-muted);
  font-size: 1rem;
}

main { max-width: 640px; margin: 0 auto; }

/* ── Card ───────────────────────────────────────────────────────── */
.quiz-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem 2rem 2.5rem;
}

/* ── Form field (question wrapper) ─────────────────────────────── */
.form-field {
  border: none;
  padding: 0;
  margin: 0;
}

.form-field + .form-field {
  margin-top: 2rem;
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
}

.form-field legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.4;
  padding: 0;
  margin-bottom: .5rem;
  width: 100%;
}

.form-field legend .question-num {
  display: inline-block;
  background: var(--color-primary);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .15em .55em;
  border-radius: 999px;
  margin-right: .45rem;
  vertical-align: middle;
  position: relative;
  top: -1px;
}

/* ── Help / error text ──────────────────────────────────────────── */
.field-help {
  font-size: .875rem;
  color: var(--color-help);
  margin-bottom: .75rem;
}

