.field-error[aria-hidden="false"],
.field-error:not([hidden]) { display: block; }

/* ── Options list ───────────────────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: .5rem;
  list-style: none;
}

/* ── Checkbox option ────────────────────────────────────────────── */
.option-label {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .75rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color .15s, background .15s, box-shadow .15s;
