const form = document.getElementById('quiz-form');
const statusEl = document.getElementById('quiz-status');

form.addEventListener('submit', (e) => {
  e.preventDefault();
  clearErrors();

  const fields = form.querySelectorAll('.form-field');
  let firstInvalid = null;

  fields.forEach((fieldset) => {
    const checked = fieldset.querySelectorAll('input[type="checkbox"]:checked');
    if (checked.length === 0) {
      markInvalid(fieldset);
      if (!firstInvalid) firstInvalid = fieldset.querySelector('input[type="checkbox"]');
    }
  });

  if (firstInvalid) {
    showStatus('error', 'Please answer every question before submitting.');
    firstInvalid.focus();
    return;
  }

  // Tally score
  let score = 0;
  fields.forEach((fieldset) => {
    const correct = JSON.parse(fieldset.dataset.correct);
    const checked = [...fieldset.querySelectorAll('input[type="checkbox"]:checked')]
      .map((cb) => cb.value);
    const allCorrectChosen = correct.every((v) => checked.includes(v));
    const noWrongChosen   = checked.every((v) => correct.includes(v));
    if (allCorrectChosen && noWrongChosen) score++;
  });

  const total = fields.length;
  showStatus('success', `You scored ${score} out of ${total}! ${score === total ? '🎉 Perfect score!' : 'Keep learning!'}`);
});

function markInvalid(fieldset) {
  fieldset.dataset.invalid = 'true';
  const errorEl = fieldset.querySelector('.field-error');
  if (errorEl) {
    errorEl.removeAttribute('hidden');
    // Update aria-describedby to include error id (idempotent)
    const currentDesc = fieldset.getAttribute('aria-describedby') || '';
    if (!currentDesc.includes(errorEl.id)) {
      fieldset.setAttribute('aria-describedby', `${currentDesc} ${errorEl.id}`.trim());
    }
  }
}

function clearErrors() {
  form.querySelectorAll('.form-field').forEach((fieldset) => {
    fieldset.dataset.invalid = 'false';
    const errorEl = fieldset.querySelector('.field-error');
    if (errorEl) {
      errorEl.setAttribute('hidden', '');
      // Remove error id from aria-describedby
      const desc = (fieldset.getAttribute('aria-describedby') || '')
        .split(' ')
        .filter((id) => id !== errorEl.id)
        .join(' ')
        .trim();
      if (desc) {
        fieldset.setAttribute('aria-describedby', desc);
      } else {
        fieldset.removeAttribute('aria-describedby');
      }
    }
  });
  hideStatus();
}

// Re-validate individual fieldsets on change so errors clear as user acts
form.addEventListener('change', (e) => {
  const fieldset = e.target.closest('.form-field');
  if (!fieldset) return;
  const checked = fieldset.querySelectorAll('input[type="checkbox"]:checked');
  if (checked.length > 0 && fieldset.dataset.invalid === 'true') {
    fieldset.dataset.invalid = 'false';
    const errorEl = fieldset.querySelector('.field-error');
    if (errorEl) {
      errorEl.setAttribute('hidden', '');
      const desc = (fieldset.getAttribute('aria-describedby') || '')
        .split(' ')
        .filter((id) => id !== errorEl.id)
        .join(' ')
        .trim();
      if (desc) fieldset.setAttribute('aria-describedby', desc);
      else fieldset.removeAttribute('aria-describedby');
    }
    // If all questions now answered, clear the status banner
    const anyInvalid = [...form.querySelectorAll('.form-field')]
      .some((f) => f.dataset.invalid === 'true');
    if (!anyInvalid) hideStatus();
  }
});

function showStatus(type, message) {
  statusEl.className = type;
  statusEl.textContent = message;
}

function hideStatus() {
  statusEl.className = '';
  statusEl.textContent = '';
