  --color-error-bg:     #fef2f2;
  --color-error-text:   #b91c1c;
  --color-error-border: #fca5a5;
  --color-success-bg:   #f0fdf4;
  --color-success-text: #15803d;
  --color-check-bg:     #4f46e5;
  --radius-sm:          6px;
  --radius-md:          10px;
  --radius-lg:          14px;
  --shadow-card:        0 1px 3px rgba(0,0,0,.08), 0 4px 12px rgba(0,0,0,.06);
  --font:               system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

/* ── Skip link ──────────────────────────────────────────────────── */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  padding: .5rem 1rem;
  background: var(--color-primary);
  color: #fff;
  border-radius: var(--radius-sm);
  font-size: .875rem;
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top .1s;
}
.skip-link:focus { top: 1rem; }

/* ── Page shell ─────────────────────────────────────────────────── */
body {
  font-family: var(--font);
  background: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  padding: 2.5rem 1rem 4rem;
  line-height: 1.6;
}

header {
  text-align: center;
  margin-bottom: 2.5rem;
}

header h1 {
  font-size: clamp(1.5rem, 4vw, 2.25rem);
  font-weight: 700;
  letter-spacing: -.02em;
  color: var(--color-text);
}

header p {
  margin-top: .5rem;
  color: var(--color-text-muted);
  font-size: 1rem;
}

main { max-width: 640px; margin: 0 auto; }

/* ── Card ───────────────────────────────────────────────────────── */
.quiz-card {
  background: var(--color-surface);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-card);
  padding: 2rem 2rem 2.5rem;
}

/* ── Form field (question wrapper) ─────────────────────────────── */
.form-field {
  border: none;
  padding: 0;
  margin: 0;
}

.form-field + .form-field {
  margin-top: 2rem;
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
}

.form-field legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--color-text);
  line-height: 1.4;
  padding: 0;
  margin-bottom: .5rem;
  width: 100%;
}

.form-field legend .question-num {
  display: inline-block;
  background: var(--color-primary);
  color: #fff;
  font-size: .7rem;
  font-weight: 700;
  letter-spacing: .04em;
  text-transform: uppercase;
  padding: .15em .55em;
  border-radius: 999px;
  margin-right: .45rem;
  vertical-align: middle;
  position: relative;
  top: -1px;
}

/* ── Help / error text ──────────────────────────────────────────── */
.field-help {
  font-size: .875rem;
  color: var(--color-help);
  margin-bottom: .75rem;
}

.field-error {
  font-size: .875rem;
  color: var(--color-error-text);
  background: var(--color-error-bg);
  border: 1px solid var(--color-error-border);
  border-radius: var(--radius-sm);
  padding: .4rem .65rem;
  margin-top: .6rem;
  display: none;
}

.field-error[aria-hidden="false"],
.field-error:not([hidden]) { display: block; }

/* ── Options list ───────────────────────────────────────────────── */
.options {
  display: flex;
  flex-direction: column;
  gap: .5rem;
  list-style: none;
}

/* ── Checkbox option ────────────────────────────────────────────── */
.option-label {
  display: flex;
  align-items: center;
  gap: .75rem;
  padding: .75rem 1rem;
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: border-color .15s, background .15s, box-shadow .15s;
  user-select: none;
  font-size: .9375rem;
}

.option-label:hover {
  border-color: var(--color-primary);
  background: #f5f3ff;
}

/* Hide native checkbox visually but keep it accessible */
.option-label input[type="checkbox"] {
  position: absolute;
  opacity: 0;
  width: 0;
  height: 0;
}

/* Custom checkbox box */
.checkbox-box {
  flex-shrink: 0;
  width: 1.125rem;
  height: 1.125rem;
  border: 2px solid var(--color-border);
  border-radius: 4px;
  background: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color .15s, background .15s;
}

/* Checked state */
.option-label input[type="checkbox"]:checked ~ .checkbox-box {
  background: var(--color-check-bg);
  border-color: var(--color-check-bg);
}

.option-label input[type="checkbox"]:checked ~ .checkbox-box::after {
  content: "";
  display: block;
  width: .35rem;
  height: .6rem;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg) translate(-1px, -1px);
}

/* Focus-visible ring on the label */
.option-label:has(input[type="checkbox"]:focus-visible) {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 2px;
  border-color: var(--color-border-focus);
}

/* Selected label highlight */
.option-label:has(input[type="checkbox"]:checked) {
  border-color: var(--color-primary);
  background: #f5f3ff;
}

/* Invalid state */
.form-field[data-invalid="true"] .option-label {
  border-color: var(--color-error-border);
}

.form-field[data-invalid="true"] .option-label:has(input[type="checkbox"]:checked) {
  border-color: var(--color-primary);
}

/* ── Submit area ────────────────────────────────────────────────── */
.submit-area {
  margin-top: 2.25rem;
  padding-top: 2rem;
  border-top: 1px solid var(--color-border);
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1rem;
}

button[type="submit"] {
  padding: .75rem 2rem;
  background: var(--color-primary);
  color: #fff;
  font-family: var(--font);
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: background .15s, box-shadow .15s;
  letter-spacing: .01em;
}

button[type="submit"]:hover { background: var(--color-primary-dark); }

button[type="submit"]:focus-visible {
  outline: 3px solid var(--color-border-focus);
  outline-offset: 3px;
  background: var(--color-primary-dark);
}

/* ── Status / result message ────────────────────────────────────── */
#quiz-status {
  font-size: .9375rem;
  border-radius: var(--radius-md);
  padding: .85rem 1.1rem;
  display: none;
}

#quiz-status.success {
  display: block;
  background: var(--color-success-bg);
  color: var(--color-success-text);
  border: 1px solid #bbf7d0;
}

#quiz-status.error {
  display: block;
  background: var(--color-error-bg);
  color: var(--color-error-text);
  border: 1px solid var(--color-error-border);
}

/* ── Forced-colors / high-contrast ─────────────────────────────── */
@media (forced-colors: active) {
  .checkbox-box { forced-color-adjust: none; }
